```turtle
@prefix ea:   <http://example.org/onto/assessment#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

@base <http://example.org/onto/assessment#> .

<http://example.org/onto/assessment> a owl:Ontology ;
  rdfs:label "Educational Assessment Ontology" .

#################################################################
# 1. CORE CLASS
#################################################################

ea:Assessment a owl:Class ;
  rdfs:label "Assessment" ;
  skos:altLabel "educational evaluation" ;
  rdfs:comment "The systematic process of documenting and using empirical data on the knowledge, skill, attitudes, aptitude and beliefs of learners to refine programs and improve student learning. Assessment is often used interchangeably with test but is not limited to tests." .

#################################################################
# 2. GRANULARITY AXIS
#################################################################

ea:hasGranularity a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:GranularityLevel .

ea:GranularityLevel a owl:Class ;
  rdfs:comment "Axis for the scope at which assessment is focused: the individual learner, the learning community, a course, an academic program, the institution, or the educational system." .

ea:IndividualLearnerGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:LearningCommunityGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:CourseGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:AcademicProgramGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:InstitutionGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:EducationalSystemGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .

ea:GranularityLevel owl:disjointUnionOf (
  ea:IndividualLearnerGranularity ea:LearningCommunityGranularity ea:CourseGranularity
  ea:AcademicProgramGranularity ea:InstitutionGranularity ea:EducationalSystemGranularity
) .

#################################################################
# 3. PURPOSE AXIS: Placement / Formative / Summative / Diagnostic
#################################################################

ea:hasPurpose a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:PurposeCategory .

ea:PurposeCategory a owl:Class .
ea:PlacementPurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:FormativePurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:SummativePurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:DiagnosticPurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .

ea:PurposeCategory owl:disjointUnionOf (
  ea:PlacementPurpose ea:FormativePurpose ea:SummativePurpose ea:DiagnosticPurpose
) ;
  rdfs:comment "Per 'Assessment is often divided into initial, formative, and summative categories' and 'Assessment can be divided ... Placement, formative, summative and diagnostic assessment', treated as a coordinate, exhaustive, pairwise-disjoint partition." .

ea:PlacementAssessment owl:equivalentClass [
    owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:PlacementPurpose ]
    )
  ] ;
  rdfs:label "Placement Assessment" ;
  skos:altLabel "pre-assessment", "initial assessment", "threshold knowledge test" ;
  rdfs:comment "Used to place students according to prior achievement, level of knowledge, or personal characteristics at the most appropriate point in an instructional sequence; conducted before instruction to establish a baseline; generally not graded." .

ea:FormativeAssessment owl:equivalentClass [
    owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:FormativePurpose ]
    )
  ] ;
  rdfs:label "Formative Assessment" ;
  skos:altLabel "educative assessment", "assessment for learning", "formative evaluation", "formative feedback", "classroom assessment" ;
  rdfs:comment "Carried out throughout a course or project to help learning; typically not used for grading; provides ongoing feedback to modify teaching and learning." .

ea:SummativeAssessment owl:equivalentClass [
    owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:SummativePurpose ]
    )
  ] ;
  rdfs:label "Summative Assessment" ;
  skos:altLabel "assessment of learning", "summative evaluation" ;
  rdfs:comment "Carried out at the end of a course or project; typically graded and used to assign a course grade; evaluative in nature." .

ea:DiagnosticAssessment owl:equivalentClass [
    owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:DiagnosticPurpose ]
    )
  ] ;
  rdfs:label "Diagnostic Assessment" ;
  rdfs:comment "Focuses on the whole of the difficulties that occurred during the learning process; measures a student's current knowledge and skills to identify a suitable program of learning." .

# TENSION: coordinate list vs. subsumption claim
ea:DiagnosticAssessment rdfs:subClassOf ea:FormativeAssessment ;
  rdfs:comment "TENSION: elsewhere the corpus states 'A common form of formative assessment is diagnostic assessment' and describes formative assessment as 'including diagnostic testing', subordinating diagnostic assessment under formative assessment. This directly conflicts with the coordinate, mutually-exclusive listing of placement/formative/summative/diagnostic assessment encoded via ea:PurposeCategory's disjoint union and the AllDisjointClasses axiom below. Both claims are retained per modeling instructions." .

[] a owl:AllDisjointClasses ;
   owl:members ( ea:PlacementAssessment ea:FormativeAssessment ea:SummativeAssessment ea:DiagnosticAssessment ) ;
   rdfs:comment "Encodes the corpus's coordinate-list claim that placement, formative, summative, and diagnostic assessment are mutually exclusive categories, in tension with the subClassOf axiom making DiagnosticAssessment a subclass of FormativeAssessment." .

ea:SelfAssessment a owl:Class ;
  rdfs:subClassOf ea:DiagnosticAssessment ;
  rdfs:comment "Self-assessment is a form of diagnostic assessment in which students assess themselves." .

ea:ForwardLookingAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Asks those being assessed to consider themselves in hypothetical future situations." .

ea:BackwardLookingAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Measures how well students have learned what they were already expected to learn." .

owl:AllDisjointClasses .

ea:ContinuousAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Evaluates a student's progress throughout a prescribed course, often as an alternative to a final-examination system; often includes formative assessment." .

ea:ComplexAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Requires a rubric and an expert examiner; examples include a thesis or funding proposal." .

ea:PerformanceBasedAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Similar to summative assessment in that it focuses on achievement; a well-defined task is identified and students create, produce, or do something, often with real-world application." .

ea:AuthenticAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "The measurement of accomplishments within a realistic, practical context that is relevant outside of the school setting." .

#################################################################
# 4. OBJECTIVITY AXIS: Objective / Subjective
#################################################################

ea:hasObjectivityType a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:ObjectivityCategory ;
  rdfs:comment "Functional: 'assessment ... is often categorized as either objective or subjective'." .

ea:ObjectivityCategory a owl:Class .
ea:ObjectiveCategory a owl:Class ; rdfs:subClassOf ea:ObjectivityCategory .
ea:SubjectiveCategory a owl:Class ; rdfs:subClassOf ea:ObjectivityCategory .
ea:ObjectivityCategory owl:disjointUnionOf ( ea:ObjectiveCategory ea:SubjectiveCategory ) .

ea:ObjectiveAssessment owl:equivalentClass [
    owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasObjectivityType ; owl:someValuesFrom ea:ObjectiveCategory ]
    )
  ] ;
  rdfs:comment "A form of questioning that has a single correct answer." .

ea:SubjectiveAssessment owl:equivalentClass [
    owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasObjectivityType ; owl:someValuesFrom ea:SubjectiveCategory ]
    )
  ] ;
  rdfs:comment "A form of questioning that may have more than one correct answer, or more than one way of expressing the correct answer." .

#################################################################
# 5. FORMALITY AXIS: Formal / Informal
#################################################################

ea:hasFormalityType a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:FormalityCategory ;
  rdfs:comment "Functional: 'Assessment can be either formal or informal'." .

ea:FormalityCategory a owl:Class .
ea:FormalCategory a owl:Class ; rdfs:subClassOf ea:FormalityCategory .
ea:InformalCategory a owl:Class ; rdfs:subClassOf ea:FormalityCategory .
ea:FormalityCategory owl:disjointUnionOf ( ea:FormalCategory ea:InformalCategory ) .

ea:FormalAssessment owl:equivalentClass [
    owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasFormalityType ; owl:someValuesFrom ea:FormalCategory ]
    )
  ] ;
  rdfs:comment "Usually implies a written document, such as a test, quiz, or paper; given a numerical score or grade." .

ea:InformalAssessment owl:equivalentClass [
    owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasFormalityType ; owl:someValuesFrom ea:InformalCategory ]
    )
  ] ;
  rdfs:comment "Occurs more casually and does not contribute to a student's final grade; may include observation, checklists, rating scales, rubrics, and discussion." .

#################################################################
# 6. ADMINISTRATION-SOURCE AXIS: Internal / External
#################################################################

ea:hasAdministrationSource a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:SourceCategory .

ea:SourceCategory a owl:Class .
ea:InternalSourceCategory a owl:Class ; rdfs:subClassOf ea:SourceCategory .
ea:ExternalSourceCategory a owl:Class ; rdfs:subClassOf ea:SourceCategory .
ea:SourceCategory owl:disjointUnionOf ( ea:InternalSourceCategory ea:ExternalSourceCategory ) .

ea:InternalAssessment owl:equivalentClass [
    owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasAdministrationSource ; owl:someValuesFrom ea:InternalSourceCategory ]
    )
  ] ;
  rdfs:comment "Set and marked by the school (teachers)." .

ea:ExternalAssessment owl:equivalentClass [
    owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasAdministrationSource ; owl:someValuesFrom ea:ExternalSourceCategory ]
    )
  ] ;
  rdfs:comment "Set by the governing body and marked by unbiased personnel." .

#################################################################
# 7. REFERENCING AXIS: Criterion-referenced / Norm-referenced / Ipsative
#################################################################

ea:hasReferenceType a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:ReferenceCategory ;
  rdfs:comment "Not declared functional: 'Each method can be used to grade the same test paper' is an explicit statement of overlap between reference types for one assessment instance." .

ea:ReferenceCategory a owl:Class .
ea:CriterionReferenceCategory a owl:Class ; rdfs:subClassOf ea:ReferenceCategory .
ea:NormReferenceCategory a owl:Class ; rdfs:subClassOf ea:ReferenceCategory .
ea:IpsativeReferenceCategory a owl:Class ; rdfs:subClassOf ea:ReferenceCategory .
ea:ReferenceCategory owl:disjointUnionOf ( ea:CriterionReferenceCategory ea:NormReferenceCategory ea:IpsativeReferenceCategory ) .

ea:CriterionReferencedAssessment owl:equivalentClass [
    owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasReferenceType ; owl:someValuesFrom ea:CriterionReferenceCategory ]
    )
  ] ;
  skos:altLabel "standards-based assessment" ;
  rdfs:comment "Candidates are measured against defined, objective criteria; often used to establish competence." .

ea:NormReferencedAssessment owl:equivalentClass [
    owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasReferenceType ; owl:someValuesFrom ea:NormReferenceCategory ]
    )
  ] ;
  skos:altLabel "normative assessment", "grading on the curve" ;
  rdfs:comment "Relative to the student body taking the assessment; a way of comparing students." .

ea:IpsativeAssessment owl:equivalentClass [
    owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasReferenceType ; owl:someValuesFrom ea:IpsativeReferenceCategory ]
    )
  ] ;
  rdfs:comment "Self-comparison either in the same domain over time, or comparative to other domains within the same student." .

#################################################################
# 8. TEST (subclass of Assessment) AND ITS AXES
#################################################################

ea:Test a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  skos:altLabel "examination", "exam", "evaluation" ;
  rdfs:comment "An educational assessment intended to measure a test-taker's knowledge, skill, aptitude, physical fitness, or classification in other topics. NOTE: the corpus states 'Most tests can be classified on multiple categories' (e.g., standardized AND high-stakes AND multiple-choice); the axes below are therefore modeled as independent, non-exclusive dimensions of ea:Test rather than a single disjoint partition." .

# --- Standardization axis ---
ea:hasStandardizationType a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Test ;
  rdfs:range ea:StandardizationCategory .

ea:StandardizationCategory a owl:Class .
ea:StandardizedCategory a owl:Class ; rdfs:subClassOf ea:StandardizationCategory .
ea:NonStandardizedCategory a owl:Class ; rdfs:subClassOf ea:StandardizationCategory .
ea:StandardizationCategory owl:disjointUnionOf ( ea:StandardizedCategory ea:NonStandardizedCategory ) .

ea:StandardizedTest owl:equivalentClass [
    owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasStandardizationType ; owl:someValuesFrom ea:StandardizedCategory ]
    )
  ] ;
  rdfs:comment "Administered and scored in a consistent or standard manner for all test takers." .

ea:NonStandardizedTest owl:equivalentClass [
    owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasStandardizationType ; owl:someValuesFrom ea:NonStandardizedCategory ]
    )
  ] ;
  rdfs:comment "Flexible in scope and format, and variable in difficulty." .

# --- Stakes axis ---
ea:hasStakesLevel a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Test ;
  rdfs:range ea:StakesCategory .

ea:StakesCategory a owl:Class .
ea:HighStakesCategory a owl:Class ; rdfs:subClassOf ea:StakesCategory .
ea:LowStakesCategory a owl:Class ; rdfs:subClassOf ea:StakesCategory .
ea:StakesCategory owl:disjointUnionOf ( ea:HighStakesCategory ea:LowStakesCategory ) .

ea:HighStakesTest owl:equivalentClass [
    owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasStakesLevel ; owl:someValuesFrom ea:HighStakesCategory ]
    )
  ] ;
  rdfs:comment "A test with a desired reward or important consequence for good or poor performance." .

ea:LowStakesTest owl:equivalentClass [
    owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasStakesLevel ; owl:someValuesFrom ea:LowStakesCategory ]
    )
  ] ;
  rdfs:comment "Carries low or no point value, e.g., ordinary classroom quizzes." .

# --- Score-interpretation axis ---
ea:TestScoreInterpretation a owl:Class .
ea:NormReferencedScoreInterpretation a owl:Class ; rdfs:subClassOf ea:TestScoreInterpretation .
ea:CriterionReferencedScoreInterpretation a owl:Class ; rdfs:subClassOf ea:TestScoreInterpretation .
ea:TestScoreInterpretation owl:disjointUnionOf ( ea:NormReferencedScoreInterpretation ea:CriterionReferencedScoreInterpretation ) .

ea:hasScoreInterpretation a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Test ;
  rdfs:range ea:TestScoreInterpretation ;
  rdfs:comment "'There are two types of test score interpretations: a norm-referenced score interpretation or a criterion-referenced score interpretation.'" .

ea:NormReferencedTest owl:equivalentClass [
    owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasReferenceType ; owl:someValuesFrom ea:NormReferenceCategory ]
    )
  ] ;
  skos:altLabel "NRT" ;
  rdfs:comment "Yields an estimate of the position of the tested individual in a predefined population." .

ea:CriterionReferencedTest owl:equivalentClass [
    owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasReferenceType ; owl:someValuesFrom ea:CriterionReferenceCategory ]
    )
  ] ;
  skos:altLabel "CRT", "mastery test" ;
  rdfs:comment "Uses test scores to show how well test takers performed on a given task, not how they compare to others." .

ea:CompetitiveExamination a owl:Class ;
  rdfs:subClassOf ea:NormReferencedTest ;
  rdfs:subClassOf ea:HighStakesTest ;
  rdfs:comment "Norm-referenced, high-stakes tests in which candidates are ranked by grade/percentile and top rankers selected." .

ea:PerformanceTest a owl:Class ;
  rdfs:subClassOf ea:Test ;
  rdfs:comment "An assessment that requires an examinee to actually perform a task or activity, rather than simply answering questions." .

# --- Standardized-test subtypes ---
ea:AchievementTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest, ea:BackwardLookingAssessment ;
  rdfs:comment "Measures knowledge and skills already learned; backward-looking." .
ea:AptitudeTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest, ea:ForwardLookingAssessment ;
  rdfs:comment "Attempts to predict ability to succeed in a future endeavor; forward-looking." .
ea:CollegeAdmissionsTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .
ea:InternationalComparisonTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .
ea:PsychologicalTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .

ea:StandardizedTest owl:disjointUnionOf (
  ea:AchievementTest ea:AptitudeTest ea:CollegeAdmissionsTest ea:InternationalComparisonTest ea:PsychologicalTest
) ;
  rdfs:comment "The corpus presents these as 'a few representative examples of the most common forms of standardized test' - treated here as an exhaustive, pairwise-disjoint partition per modeling convention, though the corpus itself hedges this as non-exhaustive." .

ea:Quiz a owl:Class ; rdfs:subClassOf ea:Test ; rdfs:comment "A brief assessment covering a small amount of material; usually a formative assessment." .
ea:MidtermExam a owl:Class ; rdfs:subClassOf ea:Test ; rdfs:comment "Given near the middle of an academic term; a type of formative or summative assessment." .
ea:FinalExam a owl:Class ; rdfs:subClassOf ea:Test ; skos:altLabel "final" ; rdfs:comment "Makes a final review of topics covered; may be the largest or only factor in course grade." .

#################################################################
# 9. TEST ITEMS AND ITEM FORMATS
#################################################################

ea:TestItem a owl:Class ; rdfs:label "Test Item" .

ea:isItemOf a owl:ObjectProperty ; rdfs:domain ea:TestItem ; rdfs:range ea:Test .
ea:hasItem a owl:ObjectProperty ; owl:inverseOf ea:isItemOf ; rdfs:domain ea:Test ; rdfs:range ea:TestItem .

ea:ObjectiveQuestion a owl:Class ; rdfs:subClassOf ea:TestItem .
ea:SubjectiveQuestion a owl:Class ; rdfs:subClassOf ea:TestItem .
[] a owl:AllDisjointClasses ; owl:members ( ea:ObjectiveQuestion ea:SubjectiveQuestion ) .

ea:TrueFalseItem a owl:Class ; rdfs:subClassOf ea:ObjectiveQuestion .
ea:MultipleChoiceItem a owl:Class ; rdfs:subClassOf ea:ObjectiveQuestion ;
  skos:altLabel "MCQ", "multiple choice question", "objective response" ;
  rdfs:comment "Consists of a stem and several alternative answers; only one answer may be keyed as correct." .
ea:MultipleResponseItem a owl:Class ; rdfs:subClassOf ea:ObjectiveQuestion ;
  rdfs:comment "More than one answer may be keyed as correct, in contrast with multiple-choice items." .
ea:MatchingItem a owl:Class ; rdfs:subClassOf ea:ObjectiveQuestion .

ea:ObjectiveQuestion owl:disjointUnionOf ( ea:TrueFalseItem ea:MultipleChoiceItem ea:MultipleResponseItem ea:MatchingItem ) .

ea:ExtendedResponseItem a owl:Class ; rdfs:subClassOf ea:SubjectiveQuestion .
ea:EssayItem a owl:Class ; rdfs:subClassOf ea:SubjectiveQuestion ;
  skos:altLabel "free response question", "FRQ", "essay question" .
ea:SubjectiveQuestion owl:disjointUnionOf ( ea:ExtendedResponseItem ea:EssayItem ) .

ea:ShortAnswerItem a owl:Class ; rdfs:subClassOf ea:ExtendedResponseItem ;
  rdfs:comment "Corpus groups 'short answer or essay' items together as requiring a written, constructed response." .

ea:FillInTheBlankItem a owl:Class ; rdfs:subClassOf ea:TestItem ;
  rdfs:comment "Provides identifying characteristics and requires recall of the correct term; may or may not supply a word bank." .

ea:MathematicalItem a owl:Class ; rdfs:subClassOf ea:TestItem ;
  rdfs:comment "Most mathematics/calculation questions 'employ a style which does not fall into any of the above categories' of objective/subjective item." .

# Multiple-choice families
ea:MultipleChoiceFamily a owl:Class ;
  rdfs:comment "'There are two families of multiple-choice questions.'" .
ea:TrueFalseQuestionFamily a owl:Class ; rdfs:subClassOf ea:MultipleChoiceFamily .
ea:OneBestAnswerQuestionFamily a owl:Class ; rdfs:subClassOf ea:MultipleChoiceFamily .
ea:MultipleChoiceFamily owl:disjointUnionOf ( ea:TrueFalseQuestionFamily ea:OneBestAnswerQuestionFamily ) .

ea:hasMultipleChoiceFamily a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:MultipleChoiceItem ;
  rdfs:range ea:MultipleChoiceFamily .

# Multiple-choice internal structure
ea:Stem a owl:Class ; rdfs:comment "The opening of a multiple-choice item: a problem, question, or incomplete statement." .
ea:AnswerOption a owl:Class .
ea:Key a owl:Class ; rdfs:subClassOf ea:AnswerOption ; rdfs:comment "The correct answer option." .
ea:Distractor a owl:Class ; rdfs:subClassOf ea:AnswerOption ; rdfs:comment "An incorrect answer option." .
ea:AnswerOption owl:disjointUnionOf ( ea:Key ea:Distractor ) .

ea:hasStem a owl:ObjectProperty, owl:FunctionalProperty ; rdfs:domain ea:MultipleChoiceItem ; rdfs:range ea:Stem .
ea:hasKey a owl:ObjectProperty, owl:FunctionalProperty ; rdfs:domain ea:MultipleChoiceItem ; rdfs:range ea:Key ;
  rdfs:comment "'Only one answer may be keyed as correct.'" .
ea:hasDistractor a owl:ObjectProperty ; rdfs:domain ea:MultipleChoiceItem ; rdfs:range ea:Distractor .

#################################################################
# 10. PERFORMANCE FORMAT: Products / Performances
#################################################################

ea:PerformanceFormat a owl:Class ;
  rdfs:comment "'Performance formats are further classified into products and performances.'" .
ea:Product a owl:Class ; rdfs:subClassOf ea:PerformanceFormat .
ea:Performance a owl:Class ; rdfs:subClassOf ea:PerformanceFormat .
ea:PerformanceFormat owl:disjointUnionOf ( ea:Product ea:Performance ) .

#################################################################
# 11. RUBRICS
#################################################################

ea:Rubric a owl:Class ;
  rdfs:comment "A scoring guide used to evaluate the quality of students' constructed responses (Popham)." .

ea:HolisticRubric a owl:Class ; rdfs:subClassOf ea:Rubric ;
  rdfs:comment "Provides an overall rating for a piece of work, considering all aspects." .
ea:AnalyticRubric a owl:Class ; rdfs:subClassOf ea:Rubric ;
  rdfs:comment "Evaluates various dimensions or components separately." .
ea:DevelopmentalRubric a owl:Class ; rdfs:subClassOf ea:Rubric ;
  rdfs:comment "Facilitates assessment, instructional design, and transformative learning through multiple dimensions of developmental succession." .

ea:Rubric owl:disjointUnionOf ( ea:HolisticRubric ea:AnalyticRubric ea:DevelopmentalRubric ) ;
  rdfs:comment "'Rubrics can be classified as holistic, analytic, or developmental' - coordinate, disjoint partition." .

ea:DevelopmentalRubric rdfs:subClassOf ea:AnalyticRubric ;
  rdfs:comment "TENSION: elsewhere the corpus states 'Developmental rubrics, a subset of analytical rubrics', subordinating developmental rubrics under analytic rubrics, in conflict with the coordinate disjoint partition above." .

ea:GradingApproach a owl:Class .
ea:HolisticGrading a owl:Class ; rdfs:subClassOf ea:GradingApproach ;
  skos:altLabel "holistic scoring", "nonreductionist grading" .
ea:AnalyticGrading a owl:Class ; rdfs:subClassOf ea:GradingApproach .
ea:TraitInformedScoring a owl:Class ; rdfs:subClassOf ea:GradingApproach ;
  rdfs:comment "'Comes close to analytic scoring methods ... however, remains holistic at heart' - explicit overlap stated in corpus, so not asserted disjoint from Holistic/Analytic grading." .
[] a owl:AllDisjointClasses ; owl:members ( ea:HolisticGrading ea:AnalyticGrading ) .

#################################################################
# 12. VALIDITY
#################################################################

ea:Validity a owl:Class ;
  rdfs:comment "The degree to which a tool measures what it claims to measure." .

ea:ContentValidity a owl:Class ; rdfs:subClassOf ea:Validity ; skos:altLabel "logical validity" .
ea:CriterionValidity a owl:Class ; rdfs:subClassOf ea:Validity ; skos:altLabel "criterion-related validity" .
ea:ConstructValidity a owl:Class ; rdfs:subClassOf ea:Validity .
ea:ConsequentialValidity a owl:Class ; rdfs:subClassOf ea:Validity .
ea:FaceValidity a owl:Class ; rdfs:subClassOf ea:Validity .

ea:Validity owl:disjointUnionOf (
  ea:ContentValidity ea:CriterionValidity ea:ConstructValidity ea:ConsequentialValidity ea:FaceValidity
) ;
  rdfs:comment "'Validity of an assessment is generally gauged through examination of evidence in the following categories: Content validity ... Criterion validity ... Construct validity ... Others are: consequential validity, face validity' - a coordinate, disjoint list." .

ea:ContentValidity rdfs:subClassOf ea:ConstructValidity .
ea:CriterionValidity rdfs:subClassOf ea:ConstructValidity .
ea:ConstructValidity rdfs:comment "TENSION: 'Construct validity ... subsumes all other types of validity' and 'Modern validity theory defines construct validity as the overarching concern of validity research, subsuming all other types of validity evidence such as content validity and criterion validity' subordinate ContentValidity and CriterionValidity under ConstructValidity, in direct conflict with the coordinate disjoint-list treatment of Validity above. Both are encoded." .

ea:ConcurrentValidity a owl:Class ; rdfs:subClassOf ea:CriterionValidity .
ea:PredictiveValidity a owl:Class ; rdfs:subClassOf ea:CriterionValidity .
ea:CriterionValidity owl:disjointUnionOf ( ea:ConcurrentValidity ea:PredictiveValidity ) ;
  rdfs:comment "'Criterion validity is often divided into concurrent and predictive validity based on the timing of measurement.'" .

ea:ConvergentValidity a owl:Class ; rdfs:subClassOf ea:ConstructValidity .
ea:DiscriminantValidity a owl:Class ; rdfs:subClassOf ea:ConstructValidity .
[] a owl:AllDisjointClasses ; owl:members ( ea:ConvergentValidity ea:DiscriminantValidity ) ;
  rdfs:comment "'Convergent and discriminant validity are the two subtypes of validity that make up construct validity.'" .

ea:hasValidity a owl:ObjectProperty ; rdfs:domain ea:Assessment ; rdfs:range ea:Validity .
ea:isValidityOf a owl:ObjectProperty ; owl:inverseOf ea:hasValidity ; rdfs:domain ea:Validity ; rdfs:range ea:Assessment .

#################################################################
# 13. RELIABILITY
#################################################################

ea:Reliability a owl:Class ;
  rdfs:comment "The consistency of an assessment: freedom of a measure from measurement error." .

ea:StudentRelatedReliability a owl:Class ; rdfs:subClassOf ea:Reliability .
ea:RaterRelatedReliability a owl:Class ; rdfs:subClassOf ea:Reliability .
ea:TestAdministrationRelatedReliability a owl:Class ; rdfs:subClassOf ea:Reliability .
ea:TestRelatedReliability a owl:Class ; rdfs:subClassOf ea:Reliability .
ea:Reliability owl:disjointUnionOf (
  ea:StudentRelatedReliability ea:RaterRelatedReliability ea:TestAdministrationRelatedReliability ea:TestRelatedReliability
) ;
  rdfs:comment "'There are four types of reliability: student-related ... rater-related ... test administration-related ... and test-related.'" .

ea:ReliabilityEstimate a owl:Class ;
  rdfs:comment "'There are several general classes of reliability estimates.'" .
ea:InterRaterReliability a owl:Class ; rdfs:subClassOf ea:ReliabilityEstimate .
ea:TestRetestReliability a owl:Class ; rdfs:subClassOf ea:ReliabilityEstimate .
ea:IntraRaterReliability a owl:Class ; rdfs:subClassOf ea:TestRetestReliability ;
  rdfs:comment "'This includes intra-rater reliability.'" .
ea:InterMethodReliability a owl:Class ; rdfs:subClassOf ea:ReliabilityEstimate ; skos:altLabel "parallel-forms reliability" .
ea:InternalConsistencyReliability a owl:Class ; rdfs:subClassOf ea:ReliabilityEstimate .

ea:ReliabilityEstimate owl:disjointUnionOf (
  ea:InterRaterReliability ea:TestRetestReliability ea:InterMethodReliability ea:InternalConsistencyReliability
) .

ea:ReliabilityEstimationMethod a owl:Class ;
  rdfs:comment "'Four practical strategies have been developed that provide workable methods of estimating test reliability.'" .
ea:TestRetestMethod a owl:Class ; rdfs:subClassOf ea:ReliabilityEstimationMethod .
ea:ParallelFormsMethod a owl:Class ; rdfs:subClassOf ea:ReliabilityEstimationMethod .
ea:SplitHalfMethod a owl:Class ; rdfs:subClassOf ea:ReliabilityEstimationMethod .
ea:InternalConsistencyMethod a owl:Class ; rdfs:subClassOf ea:ReliabilityEstimationMethod .
ea:ReliabilityEstimationMethod owl:disjointUnionOf (
  ea:TestRetestMethod ea:ParallelFormsMethod ea:SplitHalfMethod ea:InternalConsistencyMethod
) .

ea:hasReliability a owl:ObjectProperty ; rdfs:domain ea:Assessment ; rdfs:range ea:Reliability .
ea:isReliabilityOf a owl:ObjectProperty ; owl:inverseOf ea:hasReliability ; rdfs:domain ea:Reliability ; rdfs:range ea:Assessment .

ea:hasReliabilityCoefficient a owl:DatatypeProperty ; rdfs:domain ea:Reliability ; rdfs:range xsd:decimal .

#################################################################
# 14. TEST SCORE / MEASUREMENT ERROR
#################################################################

ea:TestScore a owl:Class .
ea:TrueScore a owl:Class ; rdfs:subClassOf ea:TestScore ;
  rdfs:comment "The replicable feature of the concept being measured." .
ea:ObservedScore a owl:Class ; rdfs:subClassOf ea:TestScore ;
  rdfs:comment "X = T + E, where X is observed score, T true score, E measurement error." .

ea:MeasurementError a owl:Class ;
  rdfs:comment "Composed of random error and systematic error; represents the discrepancy between an observed test score and the corresponding true score." .
ea:RandomError a owl:Class ; rdfs:subClassOf ea:MeasurementError .
ea:SystematicError a owl:Class ; rdfs:subClassOf ea:MeasurementError .
ea:MeasurementError owl:disjointUnionOf ( ea:RandomError ea:SystematicError ) .

ea:hasCutScore a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Test ; rdfs:range xsd:decimal ;
  skos:altLabel "passing score" .
ea:hasItemCount a owl:DatatypeProperty ; rdfs:domain ea:Test ; rdfs:range xsd:integer .
ea:hasEffectSize a owl:DatatypeProperty ; rdfs:domain ea:Assessment ; rdfs:range xsd:decimal .
ea:hasPercentile a owl:DatatypeProperty ; rdfs:domain ea:NormReferencedScoreInterpretation ; rdfs:range xsd:decimal .

#################################################################
# 15. LEARNING OUTCOME
#################################################################

ea:LearningOutcome a owl:Class ;
  rdfs:comment "A statement about what students should be able to do by the end of a teaching session." .
ea:IntendedLearningOutcome a owl:Class ; rdfs:subClassOf ea:LearningOutcome ; skos:altLabel "aim" .
ea:MeasuredLearningOutcome a owl:Class ; rdfs:subClassOf ea:LearningOutcome ; skos:altLabel "objective" .
ea:UnintendedLearningOutcome a owl:Class ; rdfs:subClassOf ea:LearningOutcome .
ea:LearningOutcome owl:disjointUnionOf ( ea:IntendedLearningOutcome ea:MeasuredLearningOutcome ea:UnintendedLearningOutcome ) ;
  rdfs:comment "'One can equate aims to intended learning outcomes and objectives to measured learning outcomes. A third category of learning outcome is the unintended learning outcome.'" .

ea:hasLearningOutcome a owl:ObjectProperty ; rdfs:domain ea:Assessment ; rdfs:range ea:LearningOutcome .
ea:isLearningOutcomeOf a owl:ObjectProperty ; owl:inverseOf ea:hasLearningOutcome ; rdfs:domain ea:LearningOutcome ; rdfs:range ea:Assessment .

#################################################################
# 16. TRANSFER OF LEARNING
#################################################################

ea:TransferOfLearning a owl:Class ;
  rdfs:comment "The application of skill, knowledge or understanding to resolve a novel problem or situation." .

ea:NearTransfer a owl:Class ; rdfs:subClassOf ea:TransferOfLearning ;
  rdfs:comment "Application of skill to solve a novel problem in a similar context." .
ea:FarTransfer a owl:Class ; rdfs:subClassOf ea:TransferOfLearning ;
  rdfs:comment "Application of skill to solve a novel problem in a different context." .
ea:TransferOfLearning owl:disjointUnionOf ( ea:NearTransfer ea:FarTransfer ) .

ea:PositiveTransfer a owl:Class ; rdfs:subClassOf ea:TransferOfLearning ;
  rdfs:comment "Prior learning supports novel problem solving." .
ea:NegativeTransfer a owl:Class ; rdfs:subClassOf ea:TransferOfLearning ;
  rdfs:comment "Prior learning inhibits performance on highly correlated tasks." .
[] a owl:AllDisjointClasses ; owl:members ( ea:PositiveTransfer ea:NegativeTransfer ) .

#################################################################
# 17. LEARNING (formal / non-formal / informal) — context for assessment
#################################################################

ea:Learning a owl:Class .
ea:FormalLearning a owl:Class ; rdfs:subClassOf ea:Learning .
ea:NonFormalLearning a owl:Class ; rdfs:subClassOf ea:Learning ;
  rdfs:comment "Organized learning outside the formal learning system." .
ea:InformalLearning a owl:Class ; rdfs:subClassOf ea:Learning ;
  rdfs:comment "Less structured than non-formal learning; occurs through day-to-day experience." .
ea:Learning owl:disjointUnionOf ( ea:FormalLearning ea:NonFormalLearning ea:InformalLearning ) .

#################################################################
# 18. PORTFOLIO AND FEEDBACK
#################################################################

ea:Portfolio a owl:Class ; rdfs:subClassOf ea:Assessment ;
  rdfs:comment "A compilation of academic work and other forms of educational evidence assembled to evaluate learning progress." .
ea:DigitalPortfolio a owl:Class ; rdfs:subClassOf ea:Portfolio ; skos:altLabel "e-portfolio" .

ea:Feedback a owl:Class .
ea:CorrectiveFeedback a owl:Class ; rdfs:subClassOf ea:Feedback ;
  rdfs:comment "Must be nonevaluative, supportive, timely, and specific." .
ea:Recast a owl:Class ; rdfs:subClassOf ea:CorrectiveFeedback ;
  rdfs:comment "A subtle correction of a young child's spoken errors by a parent or caregiver." .

#################################################################
# 19. PROFICIENCY, COMPETENCY-BASED LEARNING, TEACHER EVALUATION
#################################################################

ea:Proficiency a owl:Class ;
  rdfs:comment "A level of achievement determined by standards, scales, or cut-off scores on assessments." .

ea:CompetencyBasedLearning a owl:Class ;
  skos:altLabel "proficiency-based learning", "mastery-based learning", "outcome-based learning" ;
  rdfs:comment "Systems of instruction, assessment, grading, and academic reporting based on students demonstrating learned knowledge and skills." .

ea:TeacherEvaluation a owl:Class ; rdfs:subClassOf ea:SummativeAssessment ;
  rdfs:comment "'Summative assessment can be used to refer to assessment of educational faculty by their respective supervisor.'" .

ea:ValueAddedMeasure a owl:Class ; rdfs:subClassOf ea:TeacherEvaluation ; skos:altLabel "growth measure" ;
  rdfs:comment "Used to estimate how much effect individual teachers have on student learning, typically using standardized-test results." .

ea:ScoreInflation a owl:Class ;
  rdfs:comment "Results when student scores increase without a genuine improvement in learning." .

#################################################################
# 20. ASSESSMENT-TYPES LIST (explicit non-exclusivity)
#################################################################

ea:FormativeAssessment rdfs:seeAlso ea:SummativeAssessment .

[] a owl:AllDisjointClasses ;
   owl:members ( ea:PlacementAssessment ea:SummativeAssessment ) ;
   rdfs:comment "Retained only for the placement/summative pair which never co-occur in the corpus's primary purpose list; contrast with the explicit note that many OTHER listed 'Assessment types' (formative, summative, norm-referenced test, criterion-referenced test, performance-based assessment, authentic assessment, standardized test, non-standardized test, high-stakes test, competitive examination) are NOT mutually exclusive, per: 'Most tests can be classified on multiple categories ... a test can be both standardized and also a high-stakes test, or standardized and also a multiple-choice test.' Accordingly no blanket disjointness is asserted across that whole list." .
